import React from 'react';
import { Box, Typography, List, ListItem, ListItemIcon, ListItemText, Button, Paper } from '@mui/material';
import { CheckCircle as CheckCircleIcon, Warning as WarningIcon, Error as ErrorIcon } from '@mui/icons-material';
import { UnderwritingReview, BankStatement, Transaction } from '../types/underwriting';

interface RiskAssessmentProps {
  review: UnderwritingReview;
  onSubmit: (approved: boolean) => void;
}

const RiskAssessment: React.FC<RiskAssessmentProps> = ({ review, onSubmit }) => {
  const determineRiskLevel = (review: UnderwritingReview): 'low' | 'medium' | 'high' => {
    // Check address validation
    const hasAddressDiscrepancies = review.addresses.some((address) => address.status === 'failed');

    // Check bank account validation
    const hasBankAccountDiscrepancies = review.bankAccounts.some((account) => account.status === 'failed');

    // Check transaction volume and risk flags
    const statements = review.bankStatements;
    const hasRiskFlags = statements.some((statement: BankStatement) => {
      const hasNegativeBalance = statement.endingBalance < 0;
      const hasLargeTransactions = statement.largeTransactions.some((t: Transaction) => t.amount > 10000);
      return hasNegativeBalance || hasLargeTransactions;
    });

    if (hasAddressDiscrepancies || hasBankAccountDiscrepancies) {
      return 'high';
    } else if (hasRiskFlags) {
      return 'medium';
    }
    return 'low';
  };

  const getAddressStatus = (review: UnderwritingReview) => {
    const failedAddresses = review.addresses.filter((address) => address.status === 'failed');
    if (failedAddresses.length === 0) {
      return { icon: <CheckCircleIcon color="success" />, text: 'All addresses validated' };
    }
    return {
      icon: <ErrorIcon color="error" />,
      text: `${failedAddresses.length} address(es) failed validation`,
    };
  };

  const getBankAccountStatus = (review: UnderwritingReview) => {
    const failedAccounts = review.bankAccounts.filter((account) => account.status === 'failed');
    if (failedAccounts.length === 0) {
      return { icon: <CheckCircleIcon color="success" />, text: 'All bank accounts validated' };
    }
    return {
      icon: <ErrorIcon color="error" />,
      text: `${failedAccounts.length} bank account(s) failed validation`,
    };
  };

  const getTransactionStatus = (review: UnderwritingReview) => {
    const hasRiskFlags = review.bankStatements.some((statement: BankStatement) => {
      const hasNegativeBalance = statement.endingBalance < 0;
      const hasLargeTransactions = statement.largeTransactions.some((t: Transaction) => t.amount > 10000);
      return hasNegativeBalance || hasLargeTransactions;
    });

    if (!hasRiskFlags) {
      return {
        icon: <CheckCircleIcon color="success" />,
        text: 'No significant transaction risks identified',
      };
    }
    return {
      icon: <WarningIcon color="warning" />,
      text: 'Potential risk flags in transaction history',
    };
  };

  const riskLevel = determineRiskLevel(review);

  return (
    <Box>
      <Typography variant="h6" gutterBottom>
        Risk Assessment Summary
      </Typography>

      <Paper sx={{ p: 3, mb: 3 }}>
        <Typography
          variant="h5"
          gutterBottom
          color={riskLevel === 'low' ? 'success.main' : riskLevel === 'medium' ? 'warning.main' : 'error.main'}
        >
          {riskLevel.toUpperCase()} RISK
        </Typography>

        <List>
          <ListItem>
            <ListItemIcon>{getAddressStatus(review).icon}</ListItemIcon>
            <ListItemText primary={getAddressStatus(review).text} />
          </ListItem>
          <ListItem>
            <ListItemIcon>{getBankAccountStatus(review).icon}</ListItemIcon>
            <ListItemText primary={getBankAccountStatus(review).text} />
          </ListItem>
          <ListItem>
            <ListItemIcon>{getTransactionStatus(review).icon}</ListItemIcon>
            <ListItemText primary={getTransactionStatus(review).text} />
          </ListItem>
        </List>

        {riskLevel === 'high' ? (
          <Typography color="error" sx={{ mt: 2 }}>
            High-risk applications require additional verification or clarification.
          </Typography>
        ) : null}
      </Paper>

      <Box sx={{ display: 'flex', gap: 2, justifyContent: 'flex-end' }}>
        {riskLevel !== 'high' && (
          <Button variant="contained" color="primary" onClick={() => onSubmit(true)}>
            Approve Review
          </Button>
        )}
        <Button variant="outlined" color="secondary" onClick={() => onSubmit(false)}>
          Request Clarification
        </Button>
      </Box>
    </Box>
  );
};

export default RiskAssessment;
