const getStatusColor = (status: UnderwritingReview['status']) => {
  switch (status) {
    case 'approved':
      return 'success';
    case 'rejected':
      return 'error';
    case 'clarification_needed':
      return 'warning';
    default:
      return 'info';
  }
};

